-- Supported User Data Model: 1.0. SYNTHETIC ILLUSTRATION ONLY, not a production migration.
-- Execute only in a new disposable database. Never run against Version 0 or personal storage.
-- MySQL-compatible record/revision/change subset. Auth, receipts, leases and lifecycle jobs omitted.
-- Canonical JSON values are portable; original request-byte hashes must not use JSON reserialization.
CREATE TABLE example_workspaces (
    workspace_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
    owner_account_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    epoch CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    change_sequence BIGINT NOT NULL
) ENGINE=InnoDB;
CREATE TABLE example_record_heads (
    workspace_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    record_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    record_type VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    revision BIGINT NOT NULL,
    change_sequence BIGINT NOT NULL,
    document JSON NOT NULL,
    PRIMARY KEY (workspace_id, record_id),
    FOREIGN KEY (workspace_id) REFERENCES example_workspaces(workspace_id)
) ENGINE=InnoDB;
CREATE TABLE example_revisions (
    workspace_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    record_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    revision BIGINT NOT NULL,
    server_envelope JSON NOT NULL,
    PRIMARY KEY (workspace_id, record_id, revision),
    FOREIGN KEY (workspace_id, record_id) REFERENCES example_record_heads(workspace_id, record_id)
) ENGINE=InnoDB;
CREATE TABLE example_changes (
    workspace_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    epoch CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    change_sequence BIGINT NOT NULL,
    record_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    revision BIGINT NOT NULL,
    PRIMARY KEY (workspace_id, epoch, change_sequence),
    FOREIGN KEY (workspace_id, record_id, revision) REFERENCES example_revisions(workspace_id, record_id, revision)
) ENGINE=InnoDB;
START TRANSACTION;
